+static int gc_diag_entry_line;
+static void *gc_diag_parent;
+static unsigned int gc_diag_seq;
+static struct gc_diag_rec
+  {
+    unsigned int commit_seq;
+    unsigned int stage;
+    unsigned int entry_line;
+    unsigned int raw_present;
+    unsigned long long cell;
+    unsigned long long raw_word;
+    unsigned long long header_address;
+    unsigned long long entry_start;
+    unsigned long long current_parent;
+    unsigned long long entry_words;
+    unsigned int footer;
+  } gc_diag_prev, gc_diag_cur;
+
+static void gc_diag_publish
+   ___P((unsigned int stage,
+         void *cell,
+         unsigned long long raw_word,
+         int raw_present,
+         void *header,
+         void *entry_start,
+         unsigned long long entry_words,
+         void *parent),
+        (stage,
+         cell,
+         raw_word,
+         raw_present,
+         header,
+         entry_start,
+         entry_words,
+         parent)
+unsigned int stage;
+void *cell;
+unsigned long long raw_word;
+int raw_present;
+void *header;
+void *entry_start;
+unsigned long long entry_words;
+void *parent;)
+{
+  unsigned int seq;
+
+  gc_diag_prev = gc_diag_cur;
+  seq = gc_diag_seq + 1;
+  gc_diag_seq = seq;
+  /* Payload is complete before the release footer. The fence is the
+     Store/Load barrier before the caller's original read. A release or
+     seq_cst store by itself is not that barrier. */
+  gc_diag_cur.stage = stage;
+  gc_diag_cur.entry_line = (unsigned int)gc_diag_entry_line;
+  gc_diag_cur.raw_present = raw_present ? 1u : 0u;
+  gc_diag_cur.cell = (unsigned long long)___CAST(___UWORD,cell);
+  gc_diag_cur.raw_word = raw_word;
+  gc_diag_cur.header_address = (unsigned long long)___CAST(___UWORD,header);
+  gc_diag_cur.entry_start = (unsigned long long)___CAST(___UWORD,entry_start);
+  gc_diag_cur.current_parent = (unsigned long long)___CAST(___UWORD,parent);
+  gc_diag_cur.entry_words = entry_words;
+  gc_diag_cur.commit_seq = seq;
+  __atomic_store_n (&gc_diag_cur.footer, seq, __ATOMIC_RELEASE);
+  __atomic_thread_fence (__ATOMIC_SEQ_CST);
+}
